    Bug 2042910 - Chat cleanupImMarkup() should nuke non-html content. r=freaktechnik

    Differential Revision: https://phabricator.services.mozilla.com/D303329

diff --git a/chat/modules/imContentSink.sys.mjs b/chat/modules/imContentSink.sys.mjs
index 177ad01f9c8..0458ce7344c 100644
--- a/chat/modules/imContentSink.sys.mjs
+++ b/chat/modules/imContentSink.sys.mjs
@@ -350,8 +350,12 @@ function cleanupNode(aNode, aRules, aTextModifiers) {
     const node = aNode.childNodes[i];
     if (
       node.nodeType == node.ELEMENT_NODE &&
-      node.namespaceURI == "http://www.w3.org/1999/xhtml"
+      node.namespaceURI != "http://www.w3.org/1999/xhtml"
     ) {
+      aNode.removeChild(node);
+      --i;
+      continue;
+    } else if (node.nodeType == node.ELEMENT_NODE) {
       // If the node is an element, check if the node is an allowed tag.
       const nodeName = node.localName;
       if (!(nodeName in aRules.tags)) {
diff --git a/chat/modules/test/test_filtering.js b/chat/modules/test/test_filtering.js
index d360f04d041..54c0c452b95 100644
--- a/chat/modules/test/test_filtering.js
+++ b/chat/modules/test/test_filtering.js
@@ -123,10 +123,31 @@ function test_table() {
   Assert.equal(table, cleanupImMarkup(table));
 }

+function test_stripNonHtmlElements() {
+  // Non-HTML elements (SVG, MathML) should be completely removed, including children.
+  Assert.equal("", cleanupImMarkup("<svg><circle/></svg>"));
+  Assert.equal(
+    "foobar",
+    cleanupImMarkup('foo<svg><script>alert("x")</script></svg>bar')
+  );
+  Assert.equal(
+    "<p>foobaz</p>",
+    cleanupImMarkup("<p>foo<svg><text>bar</text></svg>baz</p>")
+  );
+  Assert.equal("", cleanupImMarkup("<math><mi>x</mi></math>"));
+  Assert.equal(
+    "",
+    cleanupImMarkup(
+      `<svg xmlns="...svg"><style>#Chat > div { opacity: 0.1; }</style></svg>`
+    )
+  );
+}
+
 function test_allModes() {
   test_plainText();
   test_paragraphs();
   test_stripScripts();
+  test_stripNonHtmlElements();
   test_links();
   // Remove random classes.
   Assert.equal("<p>foo</p>", cleanupImMarkup('<p class="foobar">foo</p>'));
